/**
 * Character catalog, palette, transforms, and personality calibrations
 * ported from Vellum Assistant for Amiro Agent.
 */

export interface BodyShapeDefinition {
  id: string;
  viewBox: { width: number; height: number };
  faceCenter: { x: number; y: number };
  svgPath: string;
}

export interface EyePathDefinition {
  svgPath: string;
  color: string;
}

export interface EyeStyleDefinition {
  id: string;
  sourceViewBox: { width: number; height: number };
  eyeCenter: { x: number; y: number };
  paths: EyePathDefinition[];
}

export interface ColorDefinition {
  id: string;
  hex: string;
}

export interface FaceCenterOverride {
  bodyShape: string;
  eyeStyle: string;
  faceCenter: { x: number; y: number };
}

export interface CharacterComponents {
  bodyShapes: BodyShapeDefinition[];
  eyeStyles: EyeStyleDefinition[];
  colors: ColorDefinition[];
  faceCenterOverrides: FaceCenterOverride[];
}

export interface CharacterTraits {
  bodyShape: string;
  eyeStyle: string;
  color: string;
}

export interface AvatarTone {
  bg: string;
  isLight: boolean;
  fg: string;
  fgMuted: string;
  border: string;
  wash: string;
  fgDeep: string;
}

export interface AvatarTransforms {
  bodyTransform: string;
  eyeTransform: string;
}

export interface ResolvedAvatarDefinitions {
  bodyShape: BodyShapeDefinition;
  eyeStyle: EyeStyleDefinition | undefined;
  color: ColorDefinition;
}

export interface BBox {
  x: number;
  y: number;
  w: number;
  h: number;
}

export const SCLERA = "#F2F2F2";
const PUPIL = "#1A1A1A";

export const AVATAR_COLORS: ColorDefinition[] = [
  { id: "green", hex: "#4C9B50" },
  { id: "orange", hex: "#E9642F" },
  { id: "pink", hex: "#DB4B77" },
  { id: "purple", hex: "#A665C9" },
  { id: "teal", hex: "#0E9B8B" },
  { id: "yellow", hex: "#E9C91A" },
  { id: "indigo", hex: "#5856D6" },
  { id: "cobalt", hex: "#007AFF" },
];

export function accentHexForColorId(
  colorId: string | null | undefined,
): string | null {
  if (!colorId) {
    return null;
  }
  return AVATAR_COLORS.find((c) => c.id === colorId)?.hex ?? null;
}

