export const DEFAULT_CHARACTER_TRAITS: CharacterTraits = {
  bodyShape: "blob",
  eyeStyle: "grumpy",
  color: "orange",
};

function computeBodyPlacement(
  bodyShape: BodyShapeDefinition,
  size: number,
): { bodyScale: number; bodyTx: number; bodyTy: number } {
  const bodyVB = bodyShape.viewBox;
  const bodyScale = Math.min(size / bodyVB.width, size / bodyVB.height);
  const bodyTx = (size - bodyVB.width * bodyScale) / 2;
  const bodyTy = (size - bodyVB.height * bodyScale) / 2;
  return { bodyScale, bodyTx, bodyTy };
}

function computeBodyTransform(
  bodyShape: BodyShapeDefinition,
  size: number,
): string {
  const { bodyScale, bodyTx, bodyTy } = computeBodyPlacement(bodyShape, size);
  return `matrix(${bodyScale},0,0,${bodyScale},${bodyTx},${bodyTy})`;
}

export function computeTransforms(
  bodyShape: BodyShapeDefinition,
  eyeStyle: EyeStyleDefinition,
  components: CharacterComponents,
  size: number,
): AvatarTransforms {
  const override = components.faceCenterOverrides.find(
    (o) => o.bodyShape === bodyShape.id && o.eyeStyle === eyeStyle.id,
  );
  const faceCenter = override ? override.faceCenter : bodyShape.faceCenter;

  const bodyVB = bodyShape.viewBox;
  const { bodyScale, bodyTx, bodyTy } = computeBodyPlacement(bodyShape, size);

  const eyeVB = eyeStyle.sourceViewBox;
  const remapScale = Math.min(
    bodyVB.width / eyeVB.width,
    bodyVB.height / eyeVB.height,
  );
  const remapTx = faceCenter.x - eyeStyle.eyeCenter.x * remapScale;
  const remapTy = faceCenter.y - eyeStyle.eyeCenter.y * remapScale;

  const composedScale = bodyScale * remapScale;
  const composedTx = bodyScale * remapTx + bodyTx;
  const composedTy = bodyScale * remapTy + bodyTy;

  return {
    bodyTransform: `matrix(${bodyScale},0,0,${bodyScale},${bodyTx},${bodyTy})`,
    eyeTransform: `matrix(${composedScale},0,0,${composedScale},${composedTx},${composedTy})`,
  };
}

export function resolveDefinitions(
  components: CharacterComponents,
  bodyShapeId: string,
  eyeStyleId: string | null | undefined,
  colorId: string,
): ResolvedAvatarDefinitions | null {
  const bodyShape = components.bodyShapes.find((b) => b.id === bodyShapeId);
  if (!bodyShape) {
    return null;
  }
  let eyeStyle: EyeStyleDefinition | undefined;
  if (eyeStyleId != null) {
    eyeStyle = components.eyeStyles.find((e) => e.id === eyeStyleId);
    if (!eyeStyle) {
      return null;
    }
  }
  const color = components.colors.find((c) => c.id === colorId);
  if (!color) {
    return null;
  }
  return { bodyShape, eyeStyle, color };
}

export function canResolveDefinitions(
  components: CharacterComponents,
  bodyShapeId: string,
  eyeStyleId: string | null | undefined,
  colorId: string,
): boolean {
  return (
    resolveDefinitions(components, bodyShapeId, eyeStyleId, colorId) !== null
  );
}

function escapeAttr(s: string): string {
  return s
    .replace(/&/g, "&amp;")
    .replace(/"/g, "&quot;")
    .replace(/</g, "&lt;")
    .replace(/>/g, "&gt;");
}

export function composeCharacterSvg(
  components: CharacterComponents,
  bodyShapeId: string,
  eyeStyleId: string | null | undefined,
  colorId: string,
  size: number = 512,
): string | null {
  const resolved = resolveDefinitions(
    components,
    bodyShapeId,
    eyeStyleId,
    colorId,
  );
  if (!resolved) {
    return null;
  }
  const { bodyShape, eyeStyle, color } = resolved;
  if (!eyeStyle) {
    const bodyTransform = computeBodyTransform(bodyShape, size);
    const bodyPath = `<path d="${escapeAttr(bodyShape.svgPath)}" fill="${escapeAttr(color.hex)}" transform="${bodyTransform}"/>`;
    return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">${bodyPath}</svg>`;
  }

  const { bodyTransform, eyeTransform } = computeTransforms(
    bodyShape,
    eyeStyle,
    components,
    size,
  );

  const bodyPath = `<path d="${escapeAttr(bodyShape.svgPath)}" fill="${escapeAttr(color.hex)}" transform="${bodyTransform}"/>`;

  const eyePaths = eyeStyle.paths
    .map(
      (p) =>
        `<path d="${escapeAttr(p.svgPath)}" fill="${escapeAttr(p.color)}" transform="${eyeTransform}"/>`,
    )
    .join("");

  return `<svg xmlns="http://www.w3.org/2000/svg" width="${size}" height="${size}" viewBox="0 0 ${size} ${size}">${bodyPath}${eyePaths}</svg>`;
}

export function relativeLuminance(hex: string): number {
  const m = /^#?([0-9a-f]{6})$/i.exec(hex);
  if (!m) {
    return 0;
  }
  const n = parseInt(m[1]!, 16);
  const ch = (shift: number) => {
    const c = ((n >> shift) & 0xff) / 255;
    return c <= 0.04045 ? c / 12.92 : Math.pow((c + 0.055) / 1.055, 2.4);
  };
  return 0.2126 * ch(16) + 0.7152 * ch(8) + 0.0722 * ch(0);
}

export function toneForBg(hex: string): AvatarTone {
  const lum = relativeLuminance(hex);
  // Choose the higher-contrast foreground, including mid-tone avatar colors.
  const darkContrast = (lum + 0.05) / (relativeLuminance("#141413") + 0.05);
  const lightContrast = (relativeLuminance("#FDFDFC") + 0.05) / (lum + 0.05);
  const isLight = darkContrast >= lightContrast;
  return {
    bg: hex,
    isLight,
    fg: isLight ? "#141413" : "#FDFDFC",
    fgMuted: isLight ? "rgba(20,20,19,0.68)" : "rgba(253,253,252,0.74)",
    border: isLight ? "rgba(20,20,19,0.14)" : "rgba(253,253,252,0.18)",
    wash: isLight ? "rgba(20,20,19,0.08)" : "rgba(253,253,252,0.12)",
    fgDeep: isLight ? "#000000" : "#FFFFFF",
  };
}

export interface PersonalityAxisDefinition {
  id: string;
  left: string;
  right: string;
  leftLabel: string;
  rightLabel: string;
  leftKey: string;
  rightKey: string;
}

export type PersonalityAxis = PersonalityAxisDefinition;

export const PERSONALITY_AXES: readonly PersonalityAxisDefinition[] = [
  {
    id: "companionCoworker",
    left: "Companion",
    right: "Coworker",
    leftLabel: "Companion",
    rightLabel: "Coworker",
    leftKey: "personalityAxes.companionCoworker.left",
    rightKey: "personalityAxes.companionCoworker.right",
  },
  {
    id: "genzBoomer",
    left: "Gen Z",
    right: "Baby Boomer",
    leftLabel: "Gen Z",
    rightLabel: "Baby Boomer",
    leftKey: "personalityAxes.genzBoomer.left",
    rightKey: "personalityAxes.genzBoomer.right",
  },
  {
    id: "executeCollaborate",
    left: "Independent",
    right: "Collaborative",
    leftLabel: "Independent",
    rightLabel: "Collaborative",
    leftKey: "personalityAxes.executeCollaborate.left",
    rightKey: "personalityAxes.executeCollaborate.right",
  },
  {
    id: "playfulSerious",
    left: "Playful",
    right: "Serious",
    leftLabel: "Playful",
    rightLabel: "Serious",
    leftKey: "personalityAxes.playfulSerious.left",
    rightKey: "personalityAxes.playfulSerious.right",
  },
  {
    id: "politeUnfiltered",
    left: "Polite",
    right: "Unfiltered",
    leftLabel: "Polite",
    rightLabel: "Unfiltered",
    leftKey: "personalityAxes.politeUnfiltered.left",
    rightKey: "personalityAxes.politeUnfiltered.right",
  },
] as const;

export const PERSONALITY_AXIS_DEFAULT = 50;

export const DEFAULT_PERSONALITY_SLIDERS: Record<string, number> = {
  companionCoworker: 50,
  genzBoomer: 50,
  executeCollaborate: 50,
  playfulSerious: 50,
  politeUnfiltered: 50,
};

function axisValue(values: Record<string, number>, id: string): number {
  const kebab = id.replace(/([a-z])([A-Z])/g, "$1-$2").toLowerCase();
  const raw = values[id] ?? values[kebab] ?? PERSONALITY_AXIS_DEFAULT;
  return Number.isFinite(raw)
    ? Math.max(0, Math.min(100, Math.round(raw)))
    : PERSONALITY_AXIS_DEFAULT;
}

export function summarizePersonality(values: Record<string, number>): string {
  const DEAD_ZONE = 5;
  const leans: { text: string; mag: number }[] = [];
  let balancedCount = 0;

  for (const axis of PERSONALITY_AXES) {
    const val = axisValue(values, axis.id);
    const diff = val - 50;
    if (Math.abs(diff) <= DEAD_ZONE) {
      balancedCount++;
    } else {
      const mag = Math.abs(diff);
      const text =
        diff > 0 ? `${val}% ${axis.right}` : `${100 - val}% ${axis.left}`;
      leans.push({ text, mag });
    }
  }

  if (leans.length === 0) {
    return "Balanced across all five axes";
  }

  leans.sort((a, b) => b.mag - a.mag);
  const parts = leans.slice(0, 3).map((l) => l.text);
  if (balancedCount > 0 && parts.length <= 2) {
    parts.push("Balanced tone");
  }
  return parts.join(" · ");
}

export interface BuildPersonaOverlayParams {
  name?: string;
  handle?: string;
  description?: string;
  sliders?: Record<string, number>;
  traits?: CharacterTraits;
}

export function buildPersonaOverlayMarkdown({
  name,
  handle,
  description,
  sliders = {},
  traits,
}: BuildPersonaOverlayParams): string {
  const summary = summarizePersonality(sliders);
  const lines: string[] = [
    "# Persona Overlay",
    "",
    "You are embodying the following persona profile:",
  ];

  if (name) {
    lines.push(`- **Name**: ${name}`);
  }
  if (handle) {
    lines.push(`- **Handle**: @${handle.replace(/^@/, "")}`);
  }
  if (description) {
    lines.push(`- **Bio**: ${description}`);
  }
  if (traits) {
    lines.push(
      `- **Visual Avatar**: ${traits.color} ${traits.bodyShape} (${traits.eyeStyle} eyes)`,
    );
  }
  lines.push(`- **Tone Summary**: ${summary}`);
  lines.push("");
  lines.push("## Personality Calibration (Bipolar 0-100)");

  for (const axis of PERSONALITY_AXES) {
    const val = axisValue(sliders, axis.id);
    const leanDesc =
      val <= 45
        ? `${100 - val}% ${axis.left}`
        : val >= 55
          ? `${val}% ${axis.right}`
          : "Centered";
    lines.push(
      `- **${axis.left} <-> ${axis.right}**: ${val}/100 (${leanDesc})`,
    );
  }

  lines.push("");
  lines.push("Adopt this voice and posture naturally across all interactions.");
  return lines.join("\n");
}

const NUM = /-?(?:\d+\.?\d*|\.\d+)(?:e[+-]?\d+)?/gi;
const SEGMENTS = /[MmLlHhVvCcSsQqTtAaZz][^MmLlHhVvCcSsQqTtAaZz]*/g;

export function pathBBox(d: string): BBox {
  let minX = Infinity;
  let minY = Infinity;
  let maxX = -Infinity;
  let maxY = -Infinity;
  let cx = 0;
  let cy = 0;

  const extend = (x: number, y: number) => {
    if (x < minX) minX = x;
    if (y < minY) minY = y;
    if (x > maxX) maxX = x;
    if (y > maxY) maxY = y;
  };

  const segments = d.match(SEGMENTS) ?? [];
  for (const seg of segments) {
    const code = seg[0]!;
    const upper = code.toUpperCase();
    if (upper === "Z") {
      continue;
    }
    const relative = code !== upper;
    const nums = (seg.slice(1).match(NUM) ?? []).map(Number);

    if (upper === "H") {
      for (const n of nums) {
        cx = relative ? cx + n : n;
        extend(cx, cy);
      }
    } else if (upper === "V") {
      for (const n of nums) {
        cy = relative ? cy + n : n;
        extend(cx, cy);
      }
    } else if (upper === "A") {
      for (let i = 0; i + 7 <= nums.length; i += 7) {
        const ex = nums[i + 5]!;
        const ey = nums[i + 6]!;
        cx = relative ? cx + ex : ex;
        cy = relative ? cy + ey : ey;
        extend(cx, cy);
      }
    } else {
      const startX = cx;
      const startY = cy;
      for (let i = 0; i + 2 <= nums.length; i += 2) {
        const px = relative ? startX + nums[i]! : nums[i]!;
        const py = relative ? startY + nums[i + 1]! : nums[i + 1]!;
        extend(px, py);
        if (i + 2 >= nums.length - (nums.length % 2)) {
          cx = px;
          cy = py;
        }
      }
    }
  }

  if (minX === Infinity) {
    return { x: 0, y: 0, w: 0, h: 0 };
  }
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}

export function unionBBox(boxes: BBox[]): BBox {
  if (boxes.length === 0) {
    return { x: 0, y: 0, w: 0, h: 0 };
  }
  const minX = Math.min(...boxes.map((b) => b.x));
  const minY = Math.min(...boxes.map((b) => b.y));
  const maxX = Math.max(...boxes.map((b) => b.x + b.w));
  const maxY = Math.max(...boxes.map((b) => b.y + b.h));
  return { x: minX, y: minY, w: maxX - minX, h: maxY - minY };
}
